+import { canReward } from '../src/reward';
+it('blocks unauthorized callers', () => {
+  expect(canReward({ authorized: false }, { remainingCents: 500, rewardCents: 100 })).toBe(false);
+});
+it('blocks when the budget is exhausted', () => {
+  expect(canReward({ authorized: true }, { remainingCents: 0, rewardCents: 100 })).toBe(false);
+});
+it('allows an authorized caller within budget', () => {
+  expect(canReward({ authorized: true }, { remainingCents: 500, rewardCents: 100 })).toBe(true);
+});
